Review this analytics module. The product requirement was: "don't attach identity to analytics until the user has signed in and accepted the privacy notice."

```ts
// analytics.ts
const anonymousId = getOrCreateAnonId(); // random id in localStorage, set on first visit
const buffer: Event[] = [];

export function track(name: string, props: object) {
  // while logged out, events queue locally under the anonymous id
  buffer.push({ name, props, anonymousId, ts: Date.now() });
  if (isLoggedIn()) flush();
}

export function onSignIn(userId: string) {
  // called once, right after the user authenticates and accepts the notice
  analyticsClient.identify(userId, { anonymousId });
  flush(); // send the queued events
}

function flush() {
  for (const e of buffer.splice(0)) analyticsClient.enqueue(e);
}
```

The author's PR note: "Privacy-safe: identify() is only ever called in onSignIn, i.e. after the user has signed in and consented. Nothing before that is tied to a person." A reviewer approved: "Good -- consent-gated identity, ship it."

