Review this PR that makes the notification-preferences page feel snappier. The switches now flip the moment you tap them and put themselves back if the save fails. The same page's "Save profile" button is unchanged.

```ts
// lib/api.ts — all network calls go through this wrapper
export class ApiError extends Error {}

export async function apiFetch(path: string, init?: RequestInit) {
  const res = await fetch(path, init);            // network call
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new ApiError(body.message ?? `Request failed (${res.status})`);
  }
  return res.json();
}

// lib/errors.ts
export function toUserMessage(err: unknown): string {
  if (err instanceof ApiError) return err.message;
  return "Something went wrong — please try again.";
}
```

```tsx
// ProfileForm.tsx — ordinary save, unchanged
const saveProfile = useMutation({
  mutationFn: (p: Profile) =>
    apiFetch("/api/profile", { method: "PUT", body: JSON.stringify(p) }),
  onError: (err) => toast.error(toUserMessage(err)),
});

// NotificationToggles.tsx — the new behaviour in this PR
const qc = useQueryClient();
const toggle = useMutation({
  mutationFn: (next: Prefs) =>
    apiFetch("/api/prefs", { method: "PUT", body: JSON.stringify(next) }),
  onMutate: async (next) => {
    await qc.cancelQueries({ queryKey: ["prefs"] });
    const prev = qc.getQueryData<Prefs>(["prefs"]);
    qc.setQueryData(["prefs"], next);             // reflect the switch instantly
    return { prev };
  },
  onError: (err, _next, ctx) => {
    qc.setQueryData(["prefs"], ctx?.prev);        // put the switch back
    toast.error((err as Error).message);          // and say why
  },
});
```

```tsx
// Toast.tsx — the toast host
<div aria-live="assertive" className="toast-region">{message}</div>
```

